-- Soul Runner NBA 2k27 PC Leagues: complete database setup.
-- Generated by `npm run db:sql`. Run once on an EMPTY PostgreSQL database.
-- (To update an existing database later, use `npm run db:setup` instead.)

BEGIN;

CREATE TABLE _migrations (name TEXT PRIMARY KEY, applied_at TIMESTAMPTZ NOT NULL DEFAULT now());

-- ===== 0001_init.sql =====
-- Soul Runner NBA 2k27 PC Leagues: core schema (PostgreSQL)
-- Timestamps are stored as UTC text 'YYYY-MM-DD HH:MM:SS' so the site can show them as-is.

CREATE TABLE leagues (
  id TEXT PRIMARY KEY,               -- 'premier' | 'affiliate'
  name TEXT NOT NULL,
  season_name TEXT NOT NULL,
  blurb TEXT NOT NULL DEFAULT '',
  sort INTEGER NOT NULL DEFAULT 0
);

CREATE TABLE teams (
  id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  league_id TEXT NOT NULL REFERENCES leagues(id),
  name TEXT NOT NULL,
  owner_coach TEXT NOT NULL DEFAULT '',
  stream_url TEXT NOT NULL DEFAULT '',
  sponsors TEXT NOT NULL DEFAULT '',
  affiliated_teams TEXT NOT NULL DEFAULT '',
  UNIQUE (league_id, name)
);

-- One row per human player, keyed by Discord tag (case-insensitive).
CREATE TABLE players (
  id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  discord_tag TEXT NOT NULL,
  steam_tag TEXT NOT NULL DEFAULT '',
  created_at TEXT NOT NULL DEFAULT to_char(timezone('utc', now()), 'YYYY-MM-DD HH24:MI:SS')
);
CREATE UNIQUE INDEX players_tag ON players (lower(discord_tag));

-- Seven roster slots per team: PG, SG, SF, PF, C, 6TH, 7TH.
CREATE TABLE roster_slots (
  team_id INTEGER NOT NULL REFERENCES teams(id) ON DELETE CASCADE,
  slot TEXT NOT NULL,
  player_id INTEGER REFERENCES players(id) ON DELETE SET NULL,
  PRIMARY KEY (team_id, slot)
);

CREATE TABLE weeks (
  id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  league_id TEXT NOT NULL REFERENCES leagues(id),
  number INTEGER NOT NULL,
  phase TEXT NOT NULL DEFAULT '',     -- e.g. FIRST MEETINGS
  start_date TEXT,                    -- ISO date of the Friday
  date_label TEXT NOT NULL DEFAULT '',
  UNIQUE (league_id, number)
);

-- A best-of-3 matchup. Regular season series belong to a week;
-- playoff series use stage + slot and may have teams assigned later.
CREATE TABLE series (
  id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  league_id TEXT NOT NULL REFERENCES leagues(id),
  week_id INTEGER REFERENCES weeks(id),
  stage TEXT NOT NULL DEFAULT 'regular',   -- regular | qf | sf | final
  slot INTEGER NOT NULL DEFAULT 0,
  label TEXT NOT NULL DEFAULT '',
  home_team_id INTEGER REFERENCES teams(id),
  away_team_id INTEGER REFERENCES teams(id)
);
CREATE INDEX series_week ON series(week_id);

CREATE TABLE games (
  id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  series_id INTEGER NOT NULL REFERENCES series(id) ON DELETE CASCADE,
  game_number INTEGER NOT NULL CHECK (game_number BETWEEN 1 AND 3),
  home_score INTEGER NOT NULL DEFAULT 0,
  away_score INTEGER NOT NULL DEFAULT 0,
  forfeit TEXT CHECK (forfeit IN ('home', 'away')),  -- side that forfeited
  created_at TEXT NOT NULL DEFAULT to_char(timezone('utc', now()), 'YYYY-MM-DD HH24:MI:SS'),
  updated_at TEXT NOT NULL DEFAULT to_char(timezone('utc', now()), 'YYYY-MM-DD HH24:MI:SS'),
  UNIQUE (series_id, game_number)
);

CREATE TABLE box_scores (
  game_id INTEGER NOT NULL REFERENCES games(id) ON DELETE CASCADE,
  player_id INTEGER NOT NULL REFERENCES players(id),
  team_id INTEGER NOT NULL REFERENCES teams(id),
  pts INTEGER NOT NULL DEFAULT 0,
  reb INTEGER NOT NULL DEFAULT 0,
  ast INTEGER NOT NULL DEFAULT 0,
  stl INTEGER NOT NULL DEFAULT 0,
  blk INTEGER NOT NULL DEFAULT 0,
  tov INTEGER NOT NULL DEFAULT 0,
  pf INTEGER NOT NULL DEFAULT 0,
  fgm INTEGER NOT NULL DEFAULT 0,
  fga INTEGER NOT NULL DEFAULT 0,
  tpm INTEGER NOT NULL DEFAULT 0,
  tpa INTEGER NOT NULL DEFAULT 0,
  ftm INTEGER NOT NULL DEFAULT 0,
  fta INTEGER NOT NULL DEFAULT 0,
  PRIMARY KEY (game_id, player_id)
);
CREATE INDEX box_player ON box_scores(player_id);

-- Registration and sponsorship submissions. Private: admin only.
CREATE TABLE registrations (
  id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  kind TEXT NOT NULL CHECK (kind IN ('player', 'owner', 'sponsor')),
  data TEXT NOT NULL,                      -- JSON payload
  status TEXT NOT NULL DEFAULT 'new',      -- new | approved | archived
  created_at TEXT NOT NULL DEFAULT to_char(timezone('utc', now()), 'YYYY-MM-DD HH24:MI:SS')
);

CREATE TABLE news (
  id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  title TEXT NOT NULL,
  body TEXT NOT NULL,
  published_at TEXT NOT NULL DEFAULT to_char(timezone('utc', now()), 'YYYY-MM-DD HH24:MI:SS')
);

-- One vote per award per visitor (anonymous cookie id).
CREATE TABLE award_votes (
  award TEXT NOT NULL CHECK (award IN ('mvp', 'dpoy')),
  voter_id TEXT NOT NULL,
  player_id INTEGER NOT NULL REFERENCES players(id) ON DELETE CASCADE,
  updated_at TEXT NOT NULL DEFAULT to_char(timezone('utc', now()), 'YYYY-MM-DD HH24:MI:SS'),
  PRIMARY KEY (award, voter_id)
);

-- Free-form site settings (All-Star rosters, score, etc.) as JSON text.
CREATE TABLE settings (
  key TEXT PRIMARY KEY,
  value TEXT NOT NULL
);

-- Login and registration throttling. Lives in the database because serverless
-- instances don't share memory.
CREATE TABLE rate_limits (
  key TEXT PRIMARY KEY,
  count INTEGER NOT NULL,
  reset_at TIMESTAMPTZ NOT NULL
);

-- ===== 0002_screenshots.sql =====
-- Box score screenshots read by the ingest pipeline.
-- One row per unique image (by SHA-256) so re-uploads never pay for a second model call.
-- The image itself is stored in the row (hosts like Vercel have no persistent disk).
CREATE TABLE screenshots (
  id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  sha256 TEXT NOT NULL UNIQUE,
  mime TEXT NOT NULL,
  image BYTEA NOT NULL,
  extracted TEXT,                 -- model JSON after post-processing
  warnings TEXT NOT NULL DEFAULT '[]',
  game_id INTEGER REFERENCES games(id) ON DELETE SET NULL,
  created_at TEXT NOT NULL DEFAULT to_char(timezone('utc', now()), 'YYYY-MM-DD HH24:MI:SS')
);
CREATE INDEX screenshots_game ON screenshots(game_id);

-- ===== 0003_team_logos.sql =====
-- Team logos / mascots, uploaded by the commissioner. One image per team, stored in the database
-- (hosts like Vercel have no persistent disk). teams.logo_version changes on every upload so
-- browsers can cache /api/teams/:id/logo?v=N forever. Positive = has a logo; removing one makes it
-- negative, so a later upload still gets a URL no browser has cached.
CREATE TABLE team_logos (
  team_id INTEGER PRIMARY KEY REFERENCES teams(id) ON DELETE CASCADE,
  mime TEXT NOT NULL,
  image BYTEA NOT NULL,
  updated_at TEXT NOT NULL DEFAULT to_char(timezone('utc', now()), 'YYYY-MM-DD HH24:MI:SS')
);
ALTER TABLE teams ADD COLUMN logo_version INTEGER NOT NULL DEFAULT 0;

-- ===== 0004_scrim_queue.sql =====
-- Team scrim queue: teams mark themselves ready, the matcher pairs them, the bot opens a private
-- thread. Nothing here touches NBA 2K. The service layer is src/scrim.js.
-- These tables use real timestamps (TIMESTAMPTZ) because the matcher compares them with now().

-- One row per Discord account, created the first time someone uses the bot or logs in on the site.
CREATE TABLE users (
  id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  discord_id TEXT NOT NULL UNIQUE,
  discord_name TEXT NOT NULL DEFAULT '',
  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

ALTER TABLE teams ADD COLUMN discord_role_id TEXT;
ALTER TABLE teams ADD COLUMN skill_rating INTEGER NOT NULL DEFAULT 1000;

-- Who may act for a team. A person is on one team; a team may have more than one captain.
CREATE TABLE team_members (
  team_id INTEGER NOT NULL REFERENCES teams(id) ON DELETE CASCADE,
  user_id INTEGER NOT NULL UNIQUE REFERENCES users(id) ON DELETE CASCADE,
  role TEXT NOT NULL DEFAULT 'player' CHECK (role IN ('captain', 'player', 'sub')),
  PRIMARY KEY (team_id, user_id)
);

CREATE TABLE queue_entries (
  id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  team_id INTEGER NOT NULL REFERENCES teams(id) ON DELETE CASCADE,
  queued_by_user_id INTEGER NOT NULL REFERENCES users(id),
  mode TEXT NOT NULL CHECK (mode IN ('scrim', 'ranked')),   -- scrim is unrated
  team_size INTEGER NOT NULL CHECK (team_size BETWEEN 1 AND 5),
  available_from TIMESTAMPTZ NOT NULL DEFAULT now(),
  available_until TIMESTAMPTZ NOT NULL DEFAULT now() + interval '60 minutes',
  skill_min INTEGER,
  skill_max INTEGER,
  status TEXT NOT NULL DEFAULT 'waiting' CHECK (status IN ('waiting', 'matched', 'cancelled', 'expired')),
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
-- A team has at most one waiting entry, even if two requests race.
CREATE UNIQUE INDEX queue_one_waiting ON queue_entries (team_id) WHERE status = 'waiting';

CREATE TABLE matches (
  id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  mode TEXT NOT NULL CHECK (mode IN ('scrim', 'ranked')),
  team_size INTEGER NOT NULL,
  team_a_id INTEGER NOT NULL REFERENCES teams(id) ON DELETE CASCADE,
  team_b_id INTEGER NOT NULL REFERENCES teams(id) ON DELETE CASCADE,
  queue_entry_a_id INTEGER REFERENCES queue_entries(id) ON DELETE SET NULL,
  queue_entry_b_id INTEGER REFERENCES queue_entries(id) ON DELETE SET NULL,
  status TEXT NOT NULL DEFAULT 'pending_accept' CHECK (status IN
    ('pending_accept', 'accepted', 'in_progress', 'awaiting_result', 'completed', 'disputed', 'cancelled')),
  team_a_accepted BOOLEAN NOT NULL DEFAULT false,
  team_b_accepted BOOLEAN NOT NULL DEFAULT false,
  cancel_reason TEXT,
  host_team_id INTEGER REFERENCES teams(id) ON DELETE SET NULL,
  scheduled_for TIMESTAMPTZ,              -- for matches booked ahead; unused so far
  discord_thread_id TEXT,                 -- the private thread for both teams
  announced_status TEXT,                  -- last status the bot posted in the thread
  thread_archived BOOLEAN NOT NULL DEFAULT false,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  accepted_at TIMESTAMPTZ,
  completed_at TIMESTAMPTZ
);
CREATE INDEX matches_status ON matches (status);

CREATE TABLE match_results (
  id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  match_id INTEGER NOT NULL UNIQUE REFERENCES matches(id) ON DELETE CASCADE,
  winner_team_id INTEGER NOT NULL REFERENCES teams(id) ON DELETE CASCADE,
  team_a_score INTEGER NOT NULL,
  team_b_score INTEGER NOT NULL,
  screenshot_id INTEGER REFERENCES screenshots(id) ON DELETE SET NULL,  -- served at /api/screenshots/:id
  submitted_by_user_id INTEGER NOT NULL REFERENCES users(id),
  verified_by_user_id INTEGER REFERENCES users(id),   -- null when a commissioner confirmed on the site
  verified BOOLEAN NOT NULL DEFAULT false,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- ===== 0005_scrim_box_scores.sql =====
-- Player lines from scrim result screenshots. Kept apart from box_scores on purpose: league
-- stats, standings and awards only ever read box_scores, so scrims never count toward them.
-- Rows are written when a result is reported (src/scrim.js, reportResult). Count a row as a real
-- stat only when its match is 'completed'; a disputed or unconfirmed result keeps its rows too.
CREATE TABLE scrim_box_scores (
  id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  match_id INTEGER NOT NULL REFERENCES matches(id) ON DELETE CASCADE,
  team_id INTEGER NOT NULL REFERENCES teams(id) ON DELETE CASCADE,
  player_id INTEGER REFERENCES players(id) ON DELETE SET NULL,  -- set when the name matched a league player
  name TEXT NOT NULL,                                           -- the name as read from the screenshot
  pts INTEGER NOT NULL DEFAULT 0,
  reb INTEGER NOT NULL DEFAULT 0,
  ast INTEGER NOT NULL DEFAULT 0,
  stl INTEGER NOT NULL DEFAULT 0,
  blk INTEGER NOT NULL DEFAULT 0,
  tov INTEGER NOT NULL DEFAULT 0,
  pf INTEGER NOT NULL DEFAULT 0,
  fgm INTEGER NOT NULL DEFAULT 0,
  fga INTEGER NOT NULL DEFAULT 0,
  tpm INTEGER NOT NULL DEFAULT 0,
  tpa INTEGER NOT NULL DEFAULT 0,
  ftm INTEGER NOT NULL DEFAULT 0,
  fta INTEGER NOT NULL DEFAULT 0
);
CREATE INDEX scrim_box_match ON scrim_box_scores(match_id);
CREATE INDEX scrim_box_player ON scrim_box_scores(player_id);

-- ===== 0006_solo_queue.sql =====
-- Solo queue: single players queue with the positions they play (read from their Discord roles),
-- and the matcher seats ten of them into two teams with one PG, SG, LOCK, BACKEND and C each.
-- Separate from the team scrim queue (queue_entries, matches). See src/solo.js.
CREATE TABLE solo_matches (
  id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  status TEXT NOT NULL DEFAULT 'pending_accept'
    CHECK (status IN ('pending_accept', 'in_progress', 'completed', 'cancelled')),
  cancel_reason TEXT,
  team_a_score INTEGER,
  team_b_score INTEGER,
  reported_by_user_id INTEGER REFERENCES users(id) ON DELETE SET NULL,
  discord_thread_id TEXT,
  announced_status TEXT,                           -- last status the bot posted in the thread
  thread_archived BOOLEAN NOT NULL DEFAULT FALSE,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  started_at TIMESTAMPTZ,                          -- when the tenth player accepted
  completed_at TIMESTAMPTZ
);

-- One row per time a player queues. Once seated, the row also says where: match, side and position.
CREATE TABLE solo_queue_entries (
  id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  positions TEXT NOT NULL,                         -- what they can play, comma separated: 'PG,SG'
  status TEXT NOT NULL DEFAULT 'waiting' CHECK (status IN ('waiting', 'matched', 'cancelled', 'expired')),
  available_until TIMESTAMPTZ NOT NULL DEFAULT now() + interval '60 minutes',
  match_id INTEGER REFERENCES solo_matches(id) ON DELETE SET NULL,
  side TEXT CHECK (side IN ('A', 'B')),
  position TEXT,                                   -- the one position they were given
  accepted BOOLEAN NOT NULL DEFAULT FALSE,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE UNIQUE INDEX solo_one_waiting ON solo_queue_entries (user_id) WHERE status = 'waiting';
CREATE INDEX solo_entries_match ON solo_queue_entries (match_id);

-- ===== 0007_solo_box_scores.sql =====
-- Player lines from solo queue result screenshots. Like scrim_box_scores: kept apart from
-- box_scores, so solo games never count toward league stats, standings or awards.
-- Rows are written when the result is reported (src/solo.js, reportResult).
ALTER TABLE solo_matches ADD COLUMN screenshot_id INTEGER REFERENCES screenshots(id) ON DELETE SET NULL;

CREATE TABLE solo_box_scores (
  id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  match_id INTEGER NOT NULL REFERENCES solo_matches(id) ON DELETE CASCADE,
  side TEXT NOT NULL CHECK (side IN ('A', 'B')),               -- Team A or Team B of the solo match
  player_id INTEGER REFERENCES players(id) ON DELETE SET NULL,  -- set when the name matched a league player
  name TEXT NOT NULL,                                           -- the name as read from the screenshot
  pts INTEGER NOT NULL DEFAULT 0,
  reb INTEGER NOT NULL DEFAULT 0,
  ast INTEGER NOT NULL DEFAULT 0,
  stl INTEGER NOT NULL DEFAULT 0,
  blk INTEGER NOT NULL DEFAULT 0,
  tov INTEGER NOT NULL DEFAULT 0,
  pf INTEGER NOT NULL DEFAULT 0,
  fgm INTEGER NOT NULL DEFAULT 0,
  fga INTEGER NOT NULL DEFAULT 0,
  tpm INTEGER NOT NULL DEFAULT 0,
  tpa INTEGER NOT NULL DEFAULT 0,
  ftm INTEGER NOT NULL DEFAULT 0,
  fta INTEGER NOT NULL DEFAULT 0
);
CREATE INDEX solo_box_match ON solo_box_scores (match_id);
CREATE INDEX solo_box_player ON solo_box_scores (player_id);

INSERT INTO _migrations (name) VALUES ('0001_init.sql'), ('0002_screenshots.sql'), ('0003_team_logos.sql'), ('0004_scrim_queue.sql'), ('0005_scrim_box_scores.sql'), ('0006_solo_queue.sql'), ('0007_solo_box_scores.sql');

