INSERT INTO roster_slots (team_id, slot)
  SELECT t.id, s.slot FROM teams t CROSS JOIN (VALUES ('PG', 0), ('SG', 1), ('SF', 2), ('PF', 3), ('C', 4), ('6TH', 5), ('7TH', 6)) AS s(slot, ord) ORDER BY t.id, s.ord;

